// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency, uint256 amount) public {
        // Bound amount to avoid excessive values
        amount = bound(amount, 1, 1e30);

        // Ensure pendingFlashDecision unlockTime is expired and transfer can succeed
        vm.assume(sender != address(0) && target != address(0));

        // Set up the governance config with a dummy asset (use address(this) as a mock ERC20)
        // For simplicity, we deploy a minimal ERC20 that always transfers
        // Actually, we can use vm.etch to put a mock at the asset address
        // But the simplest is to use a real ERC20 contract; however, we can just assume the transfer succeeds
        // by using an asset that is the test contract itself

        // For the rule, we need to set the flash governance config and security params
        // We can do this through successful proposal; we are the DAO

        // First, configure flash governance with asset = address(this) so transferFrom works
        vm.startPrank(address(this));
        c.configureFlashGovernance(address(this), amount, 0, false);
        c.configureSecurityParameters(50, 100, 10); // epochSize = 100, lastFlashGovernanceAct = 0 initially
        vm.stopPrank();

        // Now call assertGovernanceApproved with the given parameters
        // In the reference contract:
        // - If emergency is true and (block.timestamp - 0) <= 100, the call reverts (epoch condition fails)
        // - If emergency is false, the epoch condition is not checked, so call succeeds

        // We need to control time: set block.timestamp to 50 so epoch condition fails (50 <= 100)
        vm.warp(50);

        // Prepare: approve transfer of tokens from sender to this contract
        // Since asset = address(this), we need to simulate transferFrom from sender
        // We can use a mock: call transferFrom from sender to this contract
        vm.prank(sender);
        // But we need the asset contract to have the approval. Since we control the test contract,
        // we can just ensure the transfer succeeds by using a mock that always returns true.
        // For simplicity, we'll assume the transfer succeeds if sender has enough balance.
        // We can give sender some tokens.
        // Actually, the simplest is to use vm.assume that the transfer will succeed; but we cannot guarantee.
        // Instead, we can deploy a minimal mock ERC20 contract that always returns true for transferFrom.
        // To keep it simple, we'll use the test contract itself as the asset, and have it implement the necessary
        // by using a fallback? No, better to use a separate mock contract.
        // Given time, let's use a simpler approach: we know that if sender is address(this) and we make the transfer
        // to ourselves, it should work. But the caller might not be address(this).
        // To avoid complexity, we can just assume the transfer succeeds via vm.assume that sender has enough allowance.
        // But that is not deterministic. Let's use a deterministic approach: deploy a bare-bones ERC20 that always returns true.

        // Actually, for a general rule, we can just test the revert behavior directly without relying on transfer success.
        // The rule: when emergency is true and epoch condition fails, the reference reverts; when emergency is false, it succeeds.
        // The mutant does the opposite.
        // So we can set up the state such that transfer will always succeed (by using a mock contract as asset that always returns true).

        // Let's deploy a simple contract that always returns true for transferFrom.
        MockERC20 mock = new MockERC20();
        // But we need to set the flash governance config to use mock's address.
        vm.startPrank(address(this));
        c.configureFlashGovernance(address(mock), amount, 0, false);
        c.configureSecurityParameters(50, 100, 10);
        vm.stopPrank();

        // Ensure sender has enough tokens and approved mock to spend
        mock.mint(sender, amount);
        vm.prank(sender);
        mock.approve(address(c), amount);

        // Now set block.timestamp to 50, so epoch condition fails (50 <= 100)
        vm.warp(50);

        // Call assertGovernanceApproved and capture revert
        // In reference: emergency=true => revert; emergency=false => succeed
        // In mutant: emergency=true => succeed; emergency=false => revert (if epoch condition fails)

        // We'll call and check if it reverts
        bool reverted;
        bytes memory result;
        (reverted, result) = address(c).call(abi.encodeWithSelector(c.assertGovernanceApproved.selector, sender, target, emergency));

        // The general rule: 
        // For the reference contract, if emergency is true then the call reverts (epoch condition fails), 
        // if emergency is false then the call succeeds.
        // So we assert: (emergency == true) == reverted
        // That is, when emergency is true, the call should revert (reverted == true).
        // When emergency is false, the call should not revert (reverted == false).
        assertTrue(emergency == reverted, "Property violated");
    }
}

contract MockERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount);
        require(allowance[from][msg.sender] >= amount);
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
}

